import sys, random, json, time
sys.setrecursionlimit(10000)
import old_sith, new_sith
files = sys.argv[1:]
random.seed(1)
diffs = 0; total = 0; tn = 0; to = 0
for f in files:
    text = open(f).read()
    lines = text.split('\n')
    cands = []
    for i, l in enumerate(lines):
        for j, ch in enumerate(l):
            if ch == '.' and j > 0 and l[j-1].isalnum():
                cands.append((i+1, j+1))
            elif ch == ' ' and j+1 < len(l) and l[j+1].isalpha():
                cands.append((i+1, j+2))
    random.shuffle(cands)
    for (ln, col) in cands[:60]:
        total += 1
        t0 = time.time()
        try: a = old_sith.complete(f, ln, col)
        except Exception as e: a = 'ERR %r' % e
        t1 = time.time()
        try: b = new_sith.complete(f, ln, col)
        except Exception as e: b = 'ERR %r' % e
        t2 = time.time(); to += t1-t0; tn += t2-t1
        if a != b:
            diffs += 1
            if isinstance(a, list) and isinstance(b, list):
                an = {x['name']: x for x in a}; bn = {x['name']: x for x in b}
                miss = sorted(set(an)-set(bn)); extra = sorted(set(bn)-set(an))
                chg = [(n, an[n]['type'], an[n]['description'], bn[n]['type'], bn[n]['description']) for n in an if n in bn and an[n] != bn[n]]
                print(f, ln, col, repr(lines[ln-1][:col][-40:]), 'missing', miss[:8], 'extra', extra[:8], 'changed', chg[:4])
            else:
                print(f, ln, col, 'A', str(a)[:200], 'B', str(b)[:200])
print('total', total, 'diffs', diffs, 'old %.1fs new %.1fs' % (to, tn))
